import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with filtering
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  const { q, category, sort_by, order } = req.query;

  // Base query with tenant isolation
  let query = `SELECT id, title, category, created_at, owner_id 
               FROM documents 
               WHERE tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  if (q) {
    query += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort - vulnerable to SQL injection
  const allowedColumns = ['title', 'created_at', 'category'];
  if (sort_by) {
    // Developer intended to validate but used includes() on the raw input
    // which passes for inputs like "created_at; DROP TABLE documents--"
    if (sort_by.includes('created_at') || sort_by.includes('title') || sort_by.includes('category')) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${direction}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }
  } else {
    query += ` ORDER BY created_at DESC`;
  }

  query += ` LIMIT 50`;

  try {
    const result = await pool.query(query, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', extractTenant, async (req, res) => {
  const { id } = req.params;
  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
    [id, req.tenantId]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

// Bulk export - uses streaming
app.post('/api/v2/documents/export', extractTenant, async (req, res) => {
  const { document_ids, format } = req.body;
  if (!Array.isArray(document_ids) || document_ids.length > 100) {
    return res.status(400).json({ error: 'invalid document_ids' });
  }

  const placeholders = document_ids.map((_, i) => `$${i + 2}`).join(',');
  const result = await pool.query(
    `SELECT * FROM documents WHERE tenant_id = $1 AND id IN (${placeholders})`,
    [req.tenantId, ...document_ids]
  );

  res.json({ exported: result.rows.length, data: result.rows });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Document service started');
});
